650	// ---------------------------------------------------------------------------
651	
652	/**
653	 * Advances the game state machine one tick.
654	 *
655	 *   'menu'      — wait for Enter/Space → countdown
656	 *   'countdown' — tick down to 0 → racing
657	 *   'racing'    — raceTime increments; when playerFinished → finished
658	 *   'finished'  — hold FINISH_DELAY seconds, then Enter/Space → menu
659	 *
660	 * @param {number} dt Delta-time in seconds
661	 */
662	R.updateStateMachine = function (dt) {
663	  var input = R.input;
664	  var state = R.state;
665	  if (!input || !state) return;
666	
667	  switch (state.phase) {
668	
669	    // ---- menu ----------------------------------------------------------
670	    case 'menu':
671	      var menuConfirm = (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) || input.confirm;
672	      if (menuConfirm) {
673	        state.phase          = 'countdown';
674	        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
675	        state._lastCountNum  = 4;
676	        state.raceTime       = 0;
677	        state.playerLap      = 0;
678	        state.playerFinished = false;
679	        state.bestLap        = Infinity;
680	        // Consume keys so a held key doesn't skip the countdown
681	        if (input._keys) { input._keys['Enter'] = false; input._keys[' '] = false; input._keys['Space'] = false; }
682	        input.confirm = false;
683	        // Trigger initial countdown
684	        if (typeof R.triggerCountdown === 'function') R.triggerCountdown(3);
685	      }
686	      break;
687	
688	    // ---- countdown -----------------------------------------------------
689	    case 'countdown':
690	      state.countdownTimer -= dt;
691	      // Allow skip with Space/Enter
692	      var skipConfirm = (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) || input.confirm;
693	      if (skipConfirm) {
694	        state.countdownTimer = 0; // skip to GO!
695	        if (input._keys) { input._keys['Enter'] = false; input._keys[' '] = false; input._keys['Space'] = false; }
696	        input.confirm = false;
697	      }
698	      var countNum = Math.ceil(state.countdownTimer);
699	      if (countNum !== state._lastCountNum && countNum >= 0) {
700	        state._lastCountNum = countNum;
701	        if (typeof R.triggerCountdown === 'function') {
702	          R.triggerCountdown(countNum > 0 ? countNum : 'GO!');
703	        }
