// ---------------------------------------------------------------------------

/**
 * Advances the game state machine one tick.
 *
 *   'menu'      — wait for Enter/Space → countdown
 *   'countdown' — tick down to 0 → racing
 *   'racing'    — raceTime increments; when playerFinished → finished
 *   'finished'  — hold FINISH_DELAY seconds, then Enter/Space → menu
 *
 * @param {number} dt Delta-time in seconds
 */
R.updateStateMachine = function (dt) {
  var input = R.input;
  var state = R.state;
  if (!input || !state) return;

  switch (state.phase) {

    // ---- menu ----------------------------------------------------------
    case 'menu':
      var menuConfirm = (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) || input.confirm;
      if (menuConfirm) {
        state.phase          = 'countdown';
        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
        state._lastCountNum  = 4;
        state.raceTime       = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
        // Consume keys so a held key doesn't skip the countdown
        if (input._keys) { input._keys['Enter'] = false; input._keys[' '] = false; input._keys['Space'] = false; }
        input.confirm = false;
        // Trigger initial countdown
        if (typeof R.triggerCountdown === 'function') R.triggerCountdown(3);
      }
      break;

    // ---- countdown -----------------------------------------------------
    case 'countdown':
      state.countdownTimer -= dt;
      // Allow skip with Space/Enter
      var skipConfirm = (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) || input.confirm;
      if (skipConfirm) {
        state.countdownTimer = 0; // skip to GO!
        if (input._keys) { input._keys['Enter'] = false; input._keys[' '] = false; input._keys['Space'] = false; }
        input.confirm = false;
      }
      var countNum = Math.ceil(state.countdownTimer);
      if (countNum !== state._lastCountNum && countNum >= 0) {
        state._lastCountNum = countNum;
        if (typeof R.triggerCountdown === 'function') {
          R.triggerCountdown(countNum > 0 ? countNum : 'GO!');
        }
      }
      if (state.countdownTimer <= 0) {
        state.countdownTimer = 0;
        state.phase          = 'racing';
        state.raceTime       = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
      }
      break;

    // ---- racing --------------------------------------------------------
    case 'racing':
      state.raceTime += dt;

      // Pause check
      if (input.pause) {
        state.phase = 'paused';
        input.pause = false;
        break;
      }
      // Check finish condition
      if (state.playerFinished) {
        state.phase       = 'finished';
        state.finishTimer = 0;
      }
      break;

    // ---- paused ---------------------------------------------------------
    case 'paused':
      if (input.pause || (input._keys && (input._keys['Escape'] || input._keys['KeyP']))) {
        state.phase = 'racing';
        input.pause = false;
        if (input._keys) { input._keys['Escape'] = false; input._keys['KeyP'] = false; }
      }
      break;

    // ---- finished ------------------------------------------------------
    case 'finished':
      state.finishTimer += dt;
      if (state.finishTimer >= R.CONFIG.FINISH_DELAY) {
        var finishedConfirm = (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) || input.confirm;
        if (finishedConfirm) {
          state.phase          = 'menu';
          state.finishTimer    = 0;
          state.raceTime       = 0;

