/**
 * Bridge: render all cars (player + AI) through the main pipeline.
 * Defined here because it depends on both R.renderPlayerCar and R.renderAICars,
 * which are defined in separate modules.
 */
R.renderCars = function (ctx) {
  if (typeof R.renderPlayerCar === 'function') { R.renderPlayerCar(); }
  if (typeof R.renderAICars    === 'function') { R.renderAICars(); }
};

R.render = function () {
  var ctx = R.ctx;
  if (!ctx) return;

  ctx.save();

  // Clear the full canvas
  ctx.clearRect(0, 0, R.CONFIG.CANVAS_WIDTH, R.CONFIG.CANVAS_HEIGHT);

  // --- world-space layers (camera-relative) -----------------------------
  _applyCameraTransform(ctx);

  if (typeof R.renderSky     === 'function') { R.renderSky(ctx); }
  if (typeof R.renderTrack   === 'function') { R.renderTrack(ctx); }
  if (typeof R.renderScenery === 'function') { R.renderScenery(ctx); }
  if (typeof R.renderCars    === 'function') { R.renderCars(ctx); }
  if (typeof R.renderEffects === 'function') { R.renderEffects(ctx); }

  // --- screen-space layers ----------------------------------------------
  ctx.restore();
  ctx.save();

  // Full menu screen during menu phase
  if (R.state && R.state.phase === 'menu' && typeof R.renderMenu === 'function') {
    R.renderMenu(ctx);
  }
  if (typeof R.renderHUD     === 'function') { R.renderHUD(ctx); }
  if (typeof R.renderOverlay === 'function') { R.renderOverlay(ctx); }

