function drawBuilding(ctx, obj, sx, sy, scale) {
  var w = obj.width * scale;
  var h = obj.height * scale;
  var x = sx - w * 0.5;
  var y = sy - h; // bottom-aligned at ground

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
