/**
 * Find the segment at a given track distance (cumulative along path).
 * Uses binary search on seg.dist. Wraps for closed circuit.
 * @param {number} trackDist
 * @returns {{ segment: object, index: number, localDist: number } | null}
 */
function getSegmentAtDist(trackDist) {
  const segs = R.track.segments;
  if (!segs || segs.length === 0) return null;
  const totalLen = R.track.totalLength || 1;
  const dist = ((trackDist % totalLen) + totalLen) % totalLen;
  let lo = 0, hi = segs.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (segs[mid].dist <= dist) lo = mid;
    else hi = mid - 1;
  }
  return { segment: segs[lo], index: lo, localDist: dist - segs[lo].dist };
}

/**
 * Calculate total distance traveled by a car (for position sorting).
 * Uses R.getTrackDistanceAt for spatial→track-distance conversion.
 * @param {object} car
 * @returns {number}
 */
function getTotalDistance(car) {
  if (car.traveled !== undefined && car.traveled > 0) return car.traveled;
  const totalLen = R.track.totalLength || 1;
  const dist = R.getTrackDistanceAt
    ? R.getTrackDistanceAt(car.x || 0, car.z || 0)
    : (car.z || 0);
  return (car.lap || 0) * totalLen + dist;
}

/**
 * Get the world position and curvature at a lookahead distance ahead.
 * Uses track distance system (correct for closed loops).
 * @param {number} trackDist — current distance along track
 * @param {number} lookahead — how far ahead to look
 * @returns {{ x: number, z: number, curvature: number }}
 */
function getTrackCenterAt(trackDist, lookahead) {
  const totalLen = R.track.totalLength || 1;
  const targetDist = ((trackDist + lookahead) % totalLen + totalLen) % totalLen;
  const pos = R.getTrackPosition(targetDist);
  return { x: pos.x, z: pos.z, curvature: pos.curvature || 0 };
}

/**
 * Get weighted upcoming curvature over a distance window.
 * Uses track distance (correct for closed loops).
 * @param {number} trackDist
 * @param {number} lookDistance
 * @returns {number}
 */
function getUpcomingCurvature(trackDist, lookDistance) {
  const segs = R.track.segments;
  if (!segs || segs.length === 0) return 0;
  const totalLen = R.track.totalLength || 1;
  let totalWeight = 0, weightedCurv = 0;
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    let d = s.dist - trackDist;
    if (d < -totalLen / 2) d += totalLen;
    if (d > totalLen / 2) d -= totalLen;
    if (d > 0 && d < lookDistance) {
      const weight = (lookDistance - d) / lookDistance;
      weightedCurv += Math.abs(s.curvature || 0) * weight;
      totalWeight += weight;
    }
  }
  return totalWeight > 0 ? weightedCurv / totalWeight : 0;
}

